from itertools import count
from math import isqrt


def prime(number):
    if number < 1:
        raise ValueError('there is no zeroth prime')

    known = []
    for candidate in prime_candidates():
        limit = isqrt(candidate)
        for divisor in known:
            if divisor > limit:
                break
            if candidate % divisor == 0:
                break
        else:
            divisor = None
        if divisor is None or divisor > limit:
            known.append(candidate)
            if len(known) == number:
                return candidate


def prime_candidates():
    yield 2
    yield 3
    for number in count(6, 6):
        yield number - 1
        yield number + 1

