def solve(data):
    pages = list(data['pages'])
    pages.extend([None] * (-len(pages) % 4))
    sheets = []
    for left in range(0, len(pages) // 2, 2):
        right = len(pages) - 1 - left
        sheets.append({
            'front': [pages[right], pages[left]],
            'back': [pages[left + 1], pages[right - 1]],
        })
    return sheets
